// Reading diagrams: re-express existing text, without extending its claims.
const configs={
 polarity:{title:'用图理解：相反的两端，怎样构成一个过程？',modes:['分别','相依','整体'],notes:['吸气与呼气方向不同，分别让我们认出两种活动。','吸气与呼气相互衔接，单独停在任何一端，都不能维持呼吸。','方向相反的活动，共同构成完整呼吸。差异与整体可以同时成立。']},
 flux:{title:'用图理解：积累、转折与循环',modes:['过程','循环'],notes:['变化有积累，也有阈值与转化；持续投入不自动保证突破。','再次遇见相似问题时，已有新的经验与条件；循环不保证自动上升。']},
 probability:{title:'用图理解：选择怎样展开可能？',modes:['路径 A','路径 B','路径 C'],notes:['投入一条路径，会发展经验、关系与能力，也形成下一次选择的条件。','换一条路径，所需条件与代价也会改变；不同路径不代表同等可行。','认真选择一种可能，同时保留学习、调整与重新回应的空间。']},
 alltime:{title:'用图理解：线性经验与时间整体',modes:['线性经验','时间整体'],notes:['记得过去、经历现在、期待未来：顺序使行动拥有具体位置。','整体共存、相互关联、动态生成：共存不等于所有事件已经凝固。']},
 mirror:{title:'用图理解：意识为何需要经验？',modes:['内在可能','相对经验','认识反馈'],notes:['概念上知道一种品质，与在关系中亲自体验它，具有不同意义。','主体与他者、关系与事件，使内在可能获得具体的表达条件。','经验丰富理解，新理解又参与下一轮创造；他者始终有自己的选择。']},
 blueprint:{title:'用图理解：同一命题，可以怎样回应？',modes:['照顾家人','创作作品','建立事业'],notes:['关于承担的命题，可以在照顾与关系中被经验。','同一命题，也可以在作品与表达中获得自己的回答。','进入共同事业，又会形成不同的选择、关系与回应。']},
 generation:{title:'用图理解：意识怎样获得实相表达？',modes:['意识层','模板层','物质实相层'],notes:['意义、意向与生命主题，提供创造的内在方向。','EE活动、协调点与内在组织，使可能性获得可成形的关系。','身体、环境、关系与事件成为经验；经验反馈持续影响新的生成。']}
};
export const hasTianVisual=id=>Boolean(configs[id]);
const node=(text,cls='',sub='')=>`<div class="tv-node ${cls}"><strong>${text}</strong>${sub?`<small>${sub}</small>`:''}</div>`;
const arrow='<span class="tv-arrow" aria-hidden="true">→</span>';
function branches(labels,start,selected){return `<div class="tv-branches">${node(start,'tv-source')}<div class="tv-fan" aria-hidden="true"><svg viewBox="0 0 300 40" preserveAspectRatio="none"><path d="M150 0V18H50V40 M150 18V40 M150 18H250V40"/></svg></div><div class="tv-options">${labels.map((s,i)=>node(s,i===selected?'tv-active':'',i===selected?'当前观察':'另一种可能')).join('')}</div></div>`;}
function diagram(id,mode){
 if(id==='polarity')return `${node('同一过程：呼吸','tv-context')}<div class="tv-polar-pair">${node('吸气',mode===0?'tv-active':'','空气进入')}<span aria-hidden="true">↔</span>${node('呼气',mode===0?'tv-active':'','空气排出')}</div>${mode===0?'<div class="tv-caption">先辨认各自的方向与作用</div>':`<div class="tv-vertical" aria-hidden="true">↓</div>${node(mode===1?'相互衔接，循环发生':'两种活动，一个完整过程','tv-active')}`}<div class="tv-caption">以正文的呼吸例子理解两端与整体。</div>`;
 if(id==='probability')return `${node('历史、环境与多主体选择','tv-context')}<div class="tv-vertical" aria-hidden="true">↓</div>${branches(['路径 A','路径 B','路径 C'],'现在的条件',mode)}<div class="tv-vertical" aria-hidden="true">↓</div>${node('新的经验 · 新的条件 · 后续可能','tv-result')}<div class="tv-caption">分支为关系示意，不表示统计几率。</div>`;
 if(id==='blueprint')return `${branches(['照顾家人','创作作品','建立事业'],'生命命题：承担',mode)}<div class="tv-vertical" aria-hidden="true">↓</div>${node('经验丰富命题，选择更新回答','tv-result')}<div class="tv-caption">蓝图定题，创造定解。情境取自正文。</div>`;
 if(id==='alltime')return `<div class="tv-time ${mode?'tv-time-whole':''}"><svg viewBox="0 0 300 220" preserveAspectRatio="none" aria-hidden="true">${mode?'<path d="M50 60L250 60L150 185Z"/>':'<path d="M50 110H250"/>'}</svg>${node('过去','tv-time-past',mode?'与整体关联':'记忆')}${node('现在','tv-time-now tv-active',mode?'相遇与回应':'经历')}${node('未来','tv-time-future',mode?'仍有创造空间':'期待')}</div><div class="tv-caption">${mode?'相互关联，仍在生成':'依次经验，不穷尽整体'} · 概念示意</div>`;
 if(id==='mirror')return `<div class="tv-chain">${node('意识',mode===0?'tv-active':'','内在可能与所知')}${arrow}${node('相对经验',mode===1?'tv-active':'','他者、关系与事件')}${arrow}${node('认识反馈',mode===2?'tv-active':'','新的理解与表达')}</div><div class="tv-return"><span aria-hidden="true">↶</span> 经验丰富意识，继续参与创造</div><div class="tv-caption">认识意义的概念示意 · 他者具有独立主体性</div>`;
 if(id==='generation')return `<div class="tv-layers">${[['意识层','意义、意向与生命主题'],['电子／模板层','EE · 协调点 · 内在组织'],['物质实相层','身体、环境、关系与事件']].map(([name,detail],i)=>`${i?'<div class="tv-vertical" aria-hidden="true">↓</div>':''}${node(name,i===mode?'tv-active':'',detail)}`).join('')}</div><div class="tv-scales">${node('个体经验','','各自的位置与体验')}${node('共享实相','','多意识协调与共同条件')}</div><div class="tv-return"><span aria-hidden="true">↶</span> 经验反馈，参与新的方向与组织</div><div class="tv-caption">三道哲学的生成模型 · 不是物理实验分层图</div>`;
 if(id==='flux')return mode?`<div class="tv-cycle">${node('相似问题','','再次遇见')}<div class="tv-vertical" aria-hidden="true">↓</div>${node('新的经验与条件','tv-active')}<div class="tv-vertical" aria-hidden="true">↓</div>${node('这一轮的回应')}<div class="tv-return"><span aria-hidden="true">↶</span> 回看：理解了什么，改变了什么？</div></div>`:`<div class="tv-chain">${node('积累','','条件持续变化')}${arrow}${node('阈值','tv-active','关键条件形成')}${arrow}${node('转化','','关系或结构改变')}</div><div class="tv-caption">最后的触发事件，需要连同长期过程一起理解。</div>`;
 return `${node('同一个问题：怎样理解一件事？','tv-context')}<div class="tv-polar-pair">${node('整体方向',mode===0?'tv-active':'','提供观察视角')}<span aria-hidden="true">↔</span>${node('具体反馈',mode===0?'tv-active':'','带来新的认识')}</div>${mode===0?'<div class="tv-caption">辨认两个视角分别看见什么</div>':`<div class="tv-vertical" aria-hidden="true">↓</div>${node(mode===1?'看见相互依存的条件':'形成能够容纳差异的理解','tv-active')}`}<div class="tv-caption">沿用正文的关系思路；调和不等于取消判断。</div>`;
}
export function tianVisual(id){const c=configs[id];if(!c)return '';return `<details class="action-fold dao-fold dao-viz" id="dao-${id}-visual" data-tian-visual="${id}"><summary>${c.title}</summary><div class="tv-content"><div class="tv-controls" role="group" aria-label="${c.title}">${c.modes.map((s,i)=>`<button type="button" data-tv-mode="${i}" aria-pressed="${i===0}">${s}</button>`).join('')}</div><figure class="tv-figure" aria-label="${c.title}"><div class="tv-drawing">${diagram(id,0)}</div><figcaption class="tv-state" role="status" aria-live="polite">${c.notes[0]}</figcaption></figure></div></details>`;}
export function initTianVisuals(root){const handlers=[];root.querySelectorAll('[data-tian-visual]').forEach(el=>{const id=el.dataset.tianVisual,c=configs[id];const handler=e=>{const b=e.target.closest('[data-tv-mode]');if(!b||!el.contains(b))return;const n=Number(b.dataset.tvMode);el.querySelectorAll('[data-tv-mode]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));el.querySelector('.tv-drawing').innerHTML=diagram(id,n);el.querySelector('.tv-state').textContent=c.notes[n];};el.addEventListener('click',handler);handlers.push(()=>el.removeEventListener('click',handler));});return ()=>handlers.forEach(f=>f());}
